'use strict';
(()=>{
const $=id=>document.getElementById(id),dialog=$('coriolisDialog'),P=CoriolisPhysics,KEY='ocean-coriolis-v1';
let state={latitude:45,heading:'north',elapsed:10800,compare:true,rate:900},running=false,last=0;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s){if([-60,-45,-30,-15,0,15,30,45,60].includes(s.latitude))state.latitude=s.latitude;if(['north','east','south','west','still'].includes(s.heading))state.heading=s.heading;if(Number.isFinite(s.elapsed))state.elapsed=Math.max(0,Math.min(P.MAX_TIME,s.elapsed));if(typeof s.compare==='boolean')state.compare=s.compare;if([450,900,1800].includes(s.rate))state.rate=s.rate}}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}
function locationText(){return state.latitude===0?'赤道 0°':(state.latitude>0?'北緯 ':'南緯 ')+Math.abs(state.latitude)+'°'}
function explanation(){if(state.heading==='still')return ['沒有初速，維持靜止','初速度為零時，這個模型的科氏項也為零，物體保持在起點。'];if(state.latitude===0)return ['赤道：此模型不偏轉','固定緯度的水平科氏項為零；實驗軌跡與對照線重合。'];return [state.latitude>0?'北半球：向運動右側偏轉':'南半球：向運動左側偏轉','右、左是相對當下運動方向。改變起始方向，再看兩個方向箭頭是否仍然互相垂直。']}
const xy=p=>[260+p.x/1000*(424/52),240-p.y/1000*(424/52)];
function path(latitude){let parts=[];const n=Math.max(1,Math.ceil(state.elapsed/180));for(let i=0;i<=n;i++){const p=xy(P.sample(latitude,state.heading,state.elapsed*i/n));parts.push((i?'L':'M')+p.map(n=>n.toFixed(3)).join(','))}return parts.join(' ')}
function vector(point,vx,vy,color,id){const mag=Math.hypot(vx,vy);if(mag<1e-12)return '';const nx=vx/mag,ny=-vy/mag;let len=38;if(nx>0)len=Math.min(len,(464-point[0])/nx);if(nx<0)len=Math.min(len,(point[0]-56)/(-nx));if(ny>0)len=Math.min(len,(444-point[1])/ny);if(ny<0)len=Math.min(len,(point[1]-36)/(-ny));len=Math.max(8,len);return '<path d="M'+point.join(',')+' L'+[point[0]+nx*len,point[1]+ny*len].join(',')+'" fill="none" stroke="'+color+'" stroke-width="2.2" marker-end="url(#'+id+')"/>'}
function render(){const p=P.sample(state.latitude,state.heading,state.elapsed),q=xy(p),counter=xy(P.sample(0,state.heading,state.elapsed)),[result,detail]=explanation(),hours=(state.elapsed/3600).toFixed(1);
$('coriolisLatitude').value=state.latitude;$('coriolisHeading').value=state.heading;$('coriolisCompare').checked=state.compare;$('coriolisRate').value=state.rate;$('coriolisTime').value=state.elapsed;$('coriolisLocation').textContent=locationText();$('coriolisClock').textContent='模型時間 '+hours+' 小時';$('coriolisResult').textContent=result;$('coriolisExplanation').textContent=detail;$('coriolisPlay').setAttribute('aria-pressed',String(running));$('coriolisQuickPlay').setAttribute('aria-pressed',String(running));$('coriolisQuickPlay').textContent=running?'Ⅱ 暫停':'▶ 播放';$('coriolisPlay').textContent=running?'Ⅱ 暫停實驗':state.elapsed>=P.MAX_TIME?'↺ 重新播放':'▶ 播放實驗';
document.querySelectorAll('[data-latitude]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.latitude)===state.latitude)));
const grid=[-20,-10,0,10,20].map(k=>{const off=k*(424/52);return '<path d="M'+(260+off)+',28 V452 M48,'+(240-off)+' H472" stroke="'+(k===0?'#a8bdb7':'#d7e2d8')+'" stroke-width="'+(k===0?1.2:.7)+'"/>'+([-20,0,20].includes(k)?'<text x="'+(260+off)+'" y="466" text-anchor="middle" font-size="11" fill="#728b8a">'+k+'</text><text x="40" y="'+(244-off)+'" text-anchor="end" font-size="11" fill="#728b8a">'+k+'</text>':'')}).join('');
const marker=(id,color)=>'<marker id="'+id+'" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0 L10 5 L0 10 Z" fill="'+color+'"/></marker>';
$('coriolisPlot').innerHTML='<title id="coriolisPlotTitle">'+locationText()+'，理想化科氏偏轉實驗</title><desc id="coriolisPlotDesc">東向為正x，北向為正y。'+hours+'小時，'+result+'。'+(state.compare?'灰色虛線是不含科氏項的對照。':'')+'</desc><defs>'+marker('lab-velocity','#bb912e')+marker('lab-force','#d8826d')+'</defs><rect x="48" y="28" width="424" height="424" rx="6" fill="#f9fbf5" stroke="#cbdacc"/>'+grid+'<g fill="#526f72" font-size="14" font-weight="600"><text x="260" y="18" text-anchor="middle">北 N</text><text x="260" y="487" text-anchor="middle">南 S</text><text x="6" y="245">西</text><text x="492" y="245">東</text></g>'+
(state.compare?'<path id="coriolisCounterTrack" d="'+path(0)+'" fill="none" stroke="#99aaa6" stroke-width="2.5" stroke-dasharray="6 5"/><circle cx="'+counter[0]+'" cy="'+counter[1]+'" r="4" fill="#9fb0ac"/>':'')+
'<path id="coriolisActualTrack" d="'+path(state.latitude)+'" fill="none" stroke="#237c7b" stroke-width="3"/><circle cx="260" cy="240" r="4" fill="#fff" stroke="#537b75"/><text x="270" y="256" font-size="11" fill="#617c7b">起點</text><circle id="coriolisParticle" cx="'+q[0]+'" cy="'+q[1]+'" r="6" fill="#237c7b" stroke="#fff" stroke-width="2"/>'+vector(q,p.u,p.v,'#bb912e','lab-velocity')+vector(q,p.ax,p.ay,'#d8826d','lab-force')}
function pause(){running=false;last=0;render();save()}
function setTime(seconds){running=false;last=0;state.elapsed=Math.max(0,Math.min(P.MAX_TIME,seconds));render();save()}
function configure(key,value){running=false;last=0;state[key]=value;state.elapsed=0;render();save()}
function frame(t){if(!running||!dialog.open)return;const dt=last?Math.min((t-last)/1000,.1):0;last=t;state.elapsed=Math.min(P.MAX_TIME,state.elapsed+dt*state.rate);if(state.elapsed>=P.MAX_TIME){running=false;save()}render();if(running)requestAnimationFrame(frame)}
function open(){window.OceanExplorer?.pauseAll();render();if(!dialog.open)dialog.showModal()}
function close(){if(dialog.open)dialog.close()}
document.querySelectorAll('[data-open-coriolis]').forEach(b=>b.onclick=open);$('closeCoriolis').onclick=close;dialog.addEventListener('close',pause);dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()});
$('coriolisLatitude').onchange=e=>configure('latitude',Number(e.target.value));document.querySelectorAll('[data-latitude]').forEach(b=>b.onclick=()=>configure('latitude',Number(b.dataset.latitude)));$('coriolisHeading').onchange=e=>configure('heading',e.target.value);$('coriolisCompare').onchange=e=>{state.compare=e.target.checked;render();save()};$('coriolisRate').onchange=e=>{state.rate=Number(e.target.value);save()};$('coriolisTime').oninput=e=>setTime(Number(e.target.value));$('coriolisReset').onclick=()=>setTime(0);$('coriolisPlay').onclick=()=>{if(running){pause();return}if(state.elapsed>=P.MAX_TIME)state.elapsed=0;running=true;last=0;render();requestAnimationFrame(frame)};$('coriolisQuickPlay').onclick=()=>$('coriolisPlay').click();document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)pause()});window.addEventListener('pagehide',save);
window.CoriolisLab={open,close,setTime,getState:()=>structuredClone({...state,running,point:P.sample(state.latitude,state.heading,state.elapsed)})};render();
})();
